const $=id=>document.getElementById(id),number=n=>Math.round(n).toLocaleString({zh:'zh-CN',ja:'ja-JP',en:'en-US'}[getLocale()]),pad=n=>String(n).padStart(2,'0');
const duration=t=>`${pad(Math.floor(t/60))}:${pad(Math.floor(t)%60)}`;
let storyContext=null,currentArt=null,prologueSeen=false;
const imageFallbacks=new Map();
const visualSource=meta=>meta?.fallback||meta?.src||'';
function indexImageFallbacks(value){if(!value||typeof value!=='object')return;if(value.src&&value.fallback)imageFallbacks.set(resourceUrl(value.src),value.fallback);for(const child of Object.values(value))if(child&&typeof child==='object')indexImageFallbacks(child);}
const chapterStoriesSeen=new Set();
function showStory(pages,onDone){if(!pages.length){onDone?.();return;}if(game?.state==='playing')game.pause('story');audio.setMode(!game?'lobby':game.boss&&!game.boss.dead&&game.state!=='finished'?'boss':'story',game?.stage.chapter??selection.chapter);storyContext={pages,index:0,onDone};showModal('story');}
function finishStory(){if(!storyContext)return;const onDone=storyContext.onDone;storyContext=null;hideModal();if(onDone){onDone();if(game?.state==='paused')audio.setMode('paused',game.stage.chapter);}else if(game?.state==='paused')game.resume();if(!game)audio.setMode('lobby',selection.chapter);}
function beginFlightStory(){const pages=[];if(!prologueSeen){pages.push(...storyPages('prologue',game.stage.chapter));prologueSeen=true;}if(!chapterStoriesSeen.has(game.stage.chapter)){pages.push(...storyPages('chapter',game.stage.chapter));chapterStoriesSeen.add(game.stage.chapter);}if(pages.length)showStory(pages);}
function replayStory(value){if(value==='ending'||value==='result'&&lastResult?.stage.chapter===8){showEnding(()=>showModal(value==='result'?'result':'archive'));return;}let pages,onDone=()=>showModal('archive');if(value==='result'){pages=[...storyPages('victory',lastResult.stage.chapter),...(lastResult.stage.chapter===8?storyPages('ending',8):[])];onDone=()=>showModal('result');}else if(value==='prologue'||value==='ending')pages=storyPages(value,value==='ending'?8:0);else{const chapter=Number(value.split('-')[1]);if(!Number.isInteger(chapter)||chapter<0||chapter>8)return;pages=[...storyPages('chapter',chapter),...storyPages('boss',chapter),...storyPages('victory',chapter)];}showStory(pages,onDone);}
let canSave=true,saveBlocked=false;
function loadProfile(){try{const raw=localStorage.getItem(STORAGE);if(!raw)return createProfile();const p=JSON.parse(raw);if(!p||p.version!==1)throw new Error('invalid-save');return normalizeProfile(p);}catch{saveBlocked=true;return createProfile();}}
const profile=loadProfile();profile.materials=normalizeMaterials(profile.materials);const selection=profile.selection,settings=profile.settings;
let game=null,renderer=null,assets=null,audio=new AudioSynth(settings,{onMusicIssue:kind=>toast(kind==='blocked'?game?'点击暂停，再继续作战以开启音乐。':'点按任意菜单按钮以开启音乐。':'背景音乐加载失败，请检查连接后重新出击。'),onSfxIssue:kind=>toast(kind==='blocked'?'点击游戏画面或试听音效以开启声音。':kind==='unsupported'?'此浏览器无法播放战斗音效，请使用 Safari 或 Chrome 打开。':'部分音效暂未加载，战斗可以继续。重新出击可重试。')}),manifest=null,busy=false,modalKind='',archiveTab='records',focusBefore=null,lastResult=null,lastMessage=null,loadFailure=null,pendingImport=null;
let selectedFlow='story',exitFlight=null;
let endingPreviewPending=new URLSearchParams(globalThis.location?.search||'').has('ending');
function tryEndingPreview(){if(endingPreviewPending&&assets&&accountReady&&profile.language){endingPreviewPending=false;showEnding();}}
let coop=null,onlineBusy=false,coopChoice={shipIndex:selection.ship,skin:profile.skins[SHIPS[selection.ship].id]},coopRenderStamp='',accountRenderStamp='',accountReady=false;
const CLOUD_GAME='https://aero-echo-sky.spy-liver.chatgpt.site/game';
const account=new Account({onProfile:applyAccountProfile,onChange:accountChanged,onIssue:(error,detail)=>{if(detail?.kind==='identity-changed')toast(onlineText('identityChanged'));else if(detail?.kind==='conflict')toast(onlineText('conflict'));}});
accountReady=!account.enabled;
let lastFrame=performance.now(),accumulator=0,clock=0,lastHud=0,messageUntil=0,toastTimer=null,keys=new Set(),pointer=null,loopStarted=false;
const ending=new EndingPlayer({audio});
function showEnding(onDone=()=>goHome(),firstClear=false){storyContext=null;exitFlight=null;hideModal();keys.clear();pointer=null;accumulator=0;$('game-hud').hidden=true;$('battle-message').classList.remove('visible');ending.start({locale:getLocale(),firstClear,onDone:()=>{lastFrame=performance.now();audio.setMode(game?'story':'lobby',game?.stage.chapter??selection.chapter);onDone();}});}
function save(){unlockAchievements(profile);if(saveBlocked||!accountReady)return;if(account.user){if(account.status!=='conflict')account.save(profile);return;}try{localStorage.setItem(STORAGE,JSON.stringify(profile));}catch{if(canSave){canSave=false;toast('浏览器未允许保存，本次可正常试玩。');}}}
function toast(text){$('toast').textContent=tr(text);$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2300);}
function updateSoundIcon(){$('sound-toggle').textContent=tr(settings.sound?'♫':'♪');$('sound-toggle').classList.toggle('muted',!settings.sound);$('sound-toggle').setAttribute('aria-label',tr(settings.sound?'关闭声音':'开启声音'));}
function currentStage(){return stageConfig(selection.chapter,selection.substage,selection.mode,selection.pace);}
function updateLobby(){const ship=SHIPS[selection.ship],ch=CHAPTERS[selection.chapter],stage=currentStage();$('ship-name').textContent=storyText(pilotForShip(selection.ship).name);$('ship-role').textContent=tr(ship.role);$('mission-number').textContent=tr(`${pad(selection.chapter+1)}—${pad(selection.mode==='boss'?3:selection.substage+1)}`);$('mission-name').textContent=tr(ch.name);$('mission-place').textContent=tr(selection.mode==='boss'?ch.boss+' · Boss 直达':stage.name+' · '+(selection.pace==='quick'?'快速试飞':'完整波次'));$('side-chapter').textContent=tr(pad(selection.chapter+1)+' / 09');$('side-name').textContent=tr(ch.name);$('side-story').textContent=tr(ch.subtitle);$('side-ship').textContent=tr(ship.name);$('side-difficulty').textContent=tr(DIFFICULTIES.find(d=>d.id===selection.difficulty).name);$('side-credits').textContent=tr(number(profile.credits));document.documentElement.style.setProperty('--cyan',ship.color);$('pilot-strip').innerHTML=pilotChoices(manifest,selection.ship);$('lobby-wallet').innerHTML=`<span title="${tr('信用点')}">${gameIcon(manifest,'currency_coin')}${number(profile.credits)}</span><span title="${tr('回声数据')}">${gameIcon(manifest,'currency_data')}${number(profile.materials.data)}</span><span title="${tr('可用天赋点')}">${gameIcon(manifest,'crystal')}${profile.points}</span>`;if(assets&&!game)void assets.forMenu();$('side-pilot').textContent=storyText(pilotForShip(selection.ship).name);const checkpoint=latestClear(profile);$('continue-route').textContent=checkpoint?tr('已通关')+' '+pad(checkpoint.chapter+1)+'—'+pad(checkpoint.substage+1):tr('尚无通关存档');updateSoundIcon();document.body.classList.toggle('no-motion',!settings.shake);document.body.classList.toggle('left-controls',settings.handedness==='left');if(assets)assets.load(assets.manifest.backgrounds[selection.chapter+1].src).catch(()=>{});save();}

function selectRoute(m,flow){if(!m)return;selectedFlow=flow;Object.assign(selection,m,{mode:flow==='boss'?'boss':'campaign'});updateLobby();}
function openModal(kind){if(busy||!profile.language)return;if(game?.state==='playing')pauseFlight();
 if(!game){if(kind==='story-mode')selectRoute(storyTarget(profile),'story');
 else if(kind==='continue')selectRoute(latestClear(profile),'story');
 else if(kind==='missions'){selectedFlow='replay';selection.mode='campaign';if(!missionCleared(profile,selection.chapter,selection.substage)){const id=Object.keys(profile.clears)[0];selectRoute(id?{chapter:Number(id[0])-1,substage:Number(id[2])-1}:{chapter:0,substage:0},'replay');}else updateLobby();}
 else if(kind==='bosses'){selectedFlow='boss';selection.mode='boss';selection.substage=2;if(!bossUnlocked(profile,selection.chapter))selection.chapter=CHAPTERS.findIndex((_,c)=>bossUnlocked(profile,c));if(selection.chapter<0)selection.chapter=0;updateLobby();}
 else if(kind==='archive')archiveTab='gallery';}
 showModal(kind);
}
function showModal(kind){const previous=modalKind;modalKind=kind;if(!$('overlay').classList.contains('open'))focusBefore=document.activeElement;const names={account:['ACCOUNT / CLOUD',onlineText('account')],online:['ONLINE / CO-OP',onlineText('online')],'story-mode':['STORY / 故事航线','故事模式'],continue:['SAVE / 最新通关','继续战斗'],bosses:['BOSS / 挑战航线','BOSS挑战'],missions:['CAMPAIGN / 航线选择','关卡选择'],hangar:['HANGAR / 飞行准备','战机机库'],archive:['ECHO / DATABASE','图库及成就'],settings:['FLIGHT / PREFERENCES','飞行设置'],help:['PILOT / MANUAL','飞行指南'],pause:['FLIGHT / PAUSED','暂停作战'],result:['MISSION / REPORT','战斗报告'],import:['SAVE / RESTORE','恢复存档'],story:['AERO ECHO',storyText(STORY_UI.storyModal)],art:['AERO ECHO',storyText(STORY_UI.gallery)]};const [kicker,title]=names[kind];$('modal-kicker').textContent=tr(kicker);$('modal-title').textContent=tr(title);$('modal-body').innerHTML=localizeHtml(kind==='account'?accountHtml():kind==='online'?onlineHtml():kind==='story'?storySceneHtml(storyContext,manifest):kind==='art'?storyArtHtml(currentArt):kind==='story-mode'?storyModeHtml(profile,selection):kind==='continue'?continueHtml(profile,selection):kind==='bosses'?bossChallengeHtml(profile,selection,manifest):kind==='missions'?missionHtml():kind==='hangar'?hangarHtml():kind==='archive'?archiveHtml():kind==='settings'?settingsHtml():kind==='help'?helpHtml():kind==='pause'?pauseHtml():kind==='import'?importHtml():resultHtml());$('overlay').classList.add('open');$('overlay').classList.toggle('story-open',kind==='story');$('close-modal').hidden=false;if(previous!==kind)$('modal-body').scrollTop=0;$('close-modal').focus({preventScroll:true});}
function rerender(){if(!modalKind)return;const scroll=$('modal-body').scrollTop;showModal(modalKind);$('modal-body').scrollTop=scroll;}
function closeModal(){if(coop?.state==='paused'){resumeCoop();return;}if(coop&&['loading','intermission','failed','finished'].includes(coop.state)&&modalKind==='online'){showModal('online');return;}if(modalKind==='story'){finishStory();return;}if(modalKind==='art'){showModal('archive');return;}if(modalKind==='import'){pendingImport=null;showModal('settings');return;}if(modalKind==='result'){goHome();return;}if(game?.state==='paused'){if(modalKind!=='pause'){showModal('pause');return;}game.resume();}hideModal();}
function hideModal(){$('overlay').classList.remove('open','story-open');modalKind='';focusBefore?.focus?.({preventScroll:true});}
function missionHtml(){return missionsHtml(profile,selection,manifest);}
function hangarHtml(){const ship=SHIPS[selection.ship],level=fleetLevel(profile),skin=profile.skins[ship.id],cost=upgradeCost(level);return `${hangarArrivalHtml()}${hangarRouteHtml(profile)}<div class="hangar-pilots">${pilotChoices(manifest,selection.ship)}</div><div class="segmented">${SHIPS.map((s,i)=>`<button class="${i===selection.ship?'active':''}" data-action="ship" data-value="${i}">${s.name}<small>${s.role}</small></button>`).join('')}</div>${pilotBiography(selection.ship,manifest)}<img class="hangar-ship" src="${visualSource(manifest?.players[ship.id][skin])}" alt="${ship.name} ${SKINS[skin]}"><div class="hangar-title"><h3>${ship.name}</h3><span class="level-pill">LV.${pad(level)}</span></div><p class="hangar-role">${ship.role} / ${ship.english}</p><p>${ship.description}</p><div class="loadout-art" aria-hidden="true">${gameIcon(manifest,SHIP_ICONS[ship.id].weapon)}${gameIcon(manifest,SHIP_ICONS[ship.id].secondary)}${gameIcon(manifest,SHIP_ICONS[ship.id].passive)}<span>${ship.passive}</span></div><div class="ship-stats"><div>${gameIcon(manifest,'fortress')}<strong>${number(ship.hp*(1+.035*(level-1)))}</strong><span>机体生命</span></div><div>${gameIcon(manifest,'shield')}<strong>${number(ship.shield*(1+.032*(level-1))*(1+.06*(profile.talents.shield||0)))}</strong><span>护盾容量</span></div><div>${gameIcon(manifest,'autocannon')}<strong>${number(ship.dps*growthStats(profile,ship.id).weapon*(1+.030*(level-1)+.00055*(level-1)**2)*(1+.04*(profile.talents.fire||0)))}</strong><span>基础 DPS</span></div></div><div class="skill-description">${gameIcon(manifest,SHIP_ICONS[ship.id].skill)}<b>主动技 / ${ship.skill}</b><p>${ship.skillText}</p></div><div class="skill-description">${gameIcon(manifest,SHIP_ICONS[ship.id].ultimate)}<b>终极技 / ${ship.ultimate}</b><p>${ship.ultText}</p></div><span class="selection-label">机体外观 / 4 SKINS · 纯外观</span><div class="skin-grid">${SKINS.map((name,i)=>`<button class="${skin===i?'active':''}" data-action="skin" data-value="${i}"><i style="--color:${['#78ccf7','#93e9d0','#819be7','#eba86d','#d19af5','#a5b6bc'][i]}"></i>${name}</button>`).join('')}</div><div class="wallet"><span>信用点 <b>${number(profile.credits)}</b></span><span>可用天赋点 <b>${profile.points}</b></span></div><button class="primary" data-action="upgrade" ${!canUpgradeHull(profile)?'disabled':''}>${level>=50?'机体已达到 LV.50':level>=trainingLevel(profile)?'通关训练后可继续强化':`强化机体 · ${number(cost)} 信用点`}</button><p class="tiny-note">机体强化由三位英雄共享，并受训练等级限制。皮肤只改变外观。</p>${trainingHtml(profile)}<span class="selection-label">飞行天赋 / 大关首通获得 2 点</span><div class="talent-grid">${TALENTS.map(t=>{const n=profile.talents[t.id]||0;return `<button class="talent-card" data-action="talent" data-value="${t.id}" ${n>=t.max||profile.points<=0?'disabled':''}>${gameIcon(manifest,TALENT_ICONS[t.id])}<span>${n} / ${t.max}</span><b>${t.name}</b><small>${t.note}</small></button>`;}).join('')}</div>${progressionHtml(profile,ship.id,manifest)}<button class="secondary" data-action="close">准备完成 · 返回</button>`;}
function archiveHtml(){return `<div class="segmented archive-tabs">${[['records','飞行记录'],['story',storyText(STORY_UI.storyArchive)],['gallery',storyText(STORY_UI.gallery)],['achievements','成就'],['enemies','敌机图鉴'],['items','物品图鉴']].map(([id,name])=>`<button class="${archiveTab===id?'active':''}" data-action="archive-tab" data-value="${id}">${name}</button>`).join('')}</div>${archiveTab==='records'?recordsHtml():archiveTab==='story'?storyHtml():archiveTab==='gallery'?storyGalleryHtml(manifest):archiveTab==='achievements'?achievementsHtml(profile):archiveTab==='items'?itemsHtml(manifest,profile.materials):enemiesHtml()}`;}
function recordsHtml(){const records=profile.records.slice().sort((a,b)=>b.score-a.score).slice(0,25);return `<p class="modal-note">此浏览器的真实飞行记录。不同关卡、难度与节奏单独保留成绩，不是联网排行榜。</p>${records.length?records.map(r=>{const [c,s]=r.id.split('-').map(Number);return `<div class="record"><div><h4>${r.mode==='boss'?'BOSS / ':r.id+' / '}${CHAPTERS[c-1].name} ${r.win?'★'.repeat(r.stars||1):'· 失利'}</h4><small>${DIFFICULTIES.find(d=>d.id===r.difficulty)?.name||'标准'} / ${r.mode==='boss'?'Boss 直达':r.pace==='quick'?'快速试飞':'完整波次'} / ${duration(r.time)} / ${SHIPS.find(s=>s.id===r.ship)?.name||'曙光-7'}</small></div><strong>${number(r.score)}</strong></div>`;}).join(''):'<div class="empty-state">尚未收到飞行报告。<br>完成一次出击，记录会出现在这里。</div>'}<div class="wallet"><span>已通关小关 <b>${Object.keys(profile.clears).length} / 27</b></span><span>发现敌机 <b>${profile.discovered.length} / 30</b></span></div>`;}
function storyHtml(){return storyArchiveHtml(manifest);}
function enemiesHtml(){return `<p class="modal-note">30 种敌机各有战术行为。实战遇到后点亮信息。</p>${ENEMIES.map(e=>{const seen=profile.discovered.includes(e.id);return `<div class="codex-card" style="opacity:${seen?1:.45}"><img src="assets/enemy-${e.id}.png" alt="${e.name}" loading="lazy"><div><small>E${pad(e.id)} / ${seen?'已遭遇':'待遭遇'}</small><h3>${e.name}</h3><p>${e.hint}</p></div></div>`;}).join('')}`;}
function settingsHtml(){const rows=[['sound','游戏声音','开启后播放音乐和战斗音效'],['music','背景音乐','关卡使用原背景音乐；首领战切换专属音乐，结束后恢复。对话与剧情不中断音乐。'],['effects','战斗音效','保留射击、锁定和技能提示音'],['shake','镜头震动','关闭后减少爆炸震屏与机库动画'],['flash','战斗闪光','关闭后移除受击与爆弹全屏闪光'],['contrast','高对比弹幕','强化敌弹边缘；危险由颜色和形状共同提示'],['numbers','伤害数字','显示伤害、擦弹与修复提示'],['detail','背景细节','关闭装饰层，减轻渲染负担'],['haptic','震动反馈','设备支持时，受击触发短震动']];return `<div class="language-setting"><span class="selection-label">语言</span><div class="segmented">${LANGUAGES.map(l=>`<button data-action="language" data-value="${l.id}" lang="${l.html}" class="${profile.language===l.id?'active':''}">${l.label}</button>`).join('')}</div></div>`+rows.map(([id,name,note])=>`<div class="setting-row"><div><strong>${name}</strong><p>${note}</p></div><button class="switch ${settings[id]?'on':''}" role="switch" aria-checked="${settings[id]}" aria-label="${name}" data-action="setting" data-value="${id}"></button></div>`).join('')+volumeSettingsHtml(settings)+`<div class="setting-row"><div><strong>音效试听</strong><p>点击播放当前战机的射击音效</p></div><button class="secondary" data-action="test-sound">试听音效</button></div>`+controlSettingsHtml()+backupSettingsHtml()+`<button class="secondary" data-action="fullscreen">进入全屏</button><p class="tiny-note">手机浏览器可通过“添加到主屏幕”减少浏览器界面遮挡。设备不支持全屏时，仍可正常试玩。</p><button class="secondary" data-action="close">完成设置</button>`;}
function helpHtml(){return `<div class="help-content"><p>按住战场任意位置拖拽。飞机从当前位置相对移动，主炮持续自动开火。中心发光点是实际碰撞核心。</p><h3>三个按钮，三种战术</h3><ul><li>主动技：${SHIPS[selection.ship].skill}。按 Q，或点击左侧技能按钮；冷却后再次使用。</li><li>爆弹：按 E，或点击 ✣。短暂前摇后清除普通敌弹并获得保护；每局 2 枚，天赋可提高容量。</li><li>终极技：击杀、命中、擦弹和破坏部件积累能量。达到 100% 后按空格或点击 ◇。</li></ul><h3>生存与奖励</h3><p>护盾承受伤害，4 秒未被击中后自动恢复。生命靠修复道具恢复。靠近敌弹擦过核心外围能充能；幽蓝-X 会额外积累相位数据。</p><p>P 升级本局火控；S 回复护盾；+ 修复生命；E 为大招电池；B 为爆弹碎片，4 枚合成 1 个爆弹。菱形金币用于局外机体强化。</p><p>使用物品图鉴查看图标和作用。小型、中型、大型物品的补给量逐级提高；完整炸弹补充一枚爆弹。分数晶体加分，蓝图与数据核心在战斗结算后存入仓库。</p><p>在机库材料工坊消耗蓝图提升武器品质，使用回声数据研究全机体共享节点。飞行设置可调整拖拽灵敏度、左右手按钮位置，并备份存档。</p><h3>读懂 Boss</h3><p>虚线或收缩圆圈表示即将攻击。激光束、双轮廓三角弹不可用爆弹清除。瞄准 Boss 前方发光的部件节点，破坏后打开核心弱点；阶段转换会改变弹幕与空间规则。</p><h3>电脑操作</h3><p>WASD / 方向键移动；Q 主动技；E 爆弹；空格大招；P / Esc 暂停。切到后台会自动暂停。</p><h3>试玩范围</h3><p>九章、27 小关、三架机体、12 款外观、30 种敌机与九个 Boss 均已制作。故事通关解锁关卡重玩与首领挑战；支持本机强化、天赋和真实成绩。</p></div><button class="primary" data-action="close">收到，准备出击</button>`;}
function pauseHtml(){return `<div class="pause-banner"><span>FLIGHT SUSPENDED</span><h3>航线保持</h3><p>${game?.stage.id} / ${game?.chapter.name} · ${duration(game?.time||0)}</p></div><button class="primary" data-action="resume">继续作战 ↗</button><button class="secondary" data-action="restart">重新出击</button><button class="secondary" data-action="settings">飞行设置</button><button class="secondary" data-action="home">返回基地</button>`;}
function resultHtml(){const r=lastResult;if(!r)return '';const stage=r.stage,ch=CHAPTERS[stage.chapter],previousBest=r.previousBest||0;const next=stage.mode==='boss'?stage.chapter<8:stage.chapter<8||stage.substage<2;return `<div class="result-header"><small>${r.win?'MISSION COMPLETE':'SIGNAL LOST'}</small><h3>${r.win?'任务完成':'航线中断'}</h3><div class="stars">${r.win?'★'.repeat(r.stars)+'☆'.repeat(3-r.stars):'◇'}</div><div class="result-score">${number(r.score)}</div><p>${r.win&&r.score>previousBest?'本航线新纪录 / NEW BEST':`本航线最高分 ${number(Math.max(previousBest,r.score))}`} · ${ch.name}</p></div><div class="result-stats"><div><span>击破敌机</span><b>${r.kills}</b></div><div><span>擦弹次数</span><b>${r.grazes}</b></div><div><span>作战时间</span><b>${duration(r.time)}</b></div><div><span>受击次数</span><b>${r.hits}</b></div></div><div class="wallet"><span>获得信用点 <b>+ ${number(r.reward)}</b></span><span>天赋点 <b>+ ${r.points}</b></span></div>${experienceReportHtml(r)}${materialReportHtml(r.materials)}${r.win?`<p class="result-story">${stage.boss?storyText(STORY.chapters[stage.chapter].victory.at(-1).text):stage.story}</p>`:'<p class="result-story">换条移动路线，提前使用爆弹。四秒没有受击，护盾会自动恢复。返回机库强化也能提高容错。</p>'}${r.win&&stage.boss?`<button class="secondary" data-action="story-replay" data-value="result">${storyText(stage.chapter===8?STORY_UI.ending:STORY_UI.victory)} ↗</button>`:''}${r.win&&next?'<button class="primary" data-action="next">下一关出击 ↗</button>':'<button class="primary" data-action="restart">再次出击 ↗</button>'}${r.win&&next?'<button class="secondary" data-action="restart">重试本关 · 挑战更高分</button>':''}<button class="secondary" data-action="home">返回基地</button>`;}

function controlSettingsHtml(){return `<span class="selection-label">手机操作</span><p class="modal-note">拖拽灵敏度决定手指移动与飞机目标移动的比例。按钮可放在左侧，方便左手操作。</p><span class="selection-label">拖拽灵敏度</span><div class="segmented">${SENSITIVITIES.map(value=>`<button data-action="sensitivity" data-value="${value}" class="${settings.sensitivity===value?'active':''}" aria-pressed="${settings.sensitivity===value}">×${value.toFixed(2)}</button>`).join('')}</div><span class="selection-label">技能按钮位置</span><div class="segmented">${[['left','左侧'],['right','右侧']].map(([value,label])=>`<button data-action="handedness" data-value="${value}" class="${settings.handedness===value?'active':''}" aria-pressed="${settings.handedness===value}">${label}</button>`).join('')}</div>`;}
function hasPreviousSave(){try{return !!localStorage.getItem(account.user?account.backupKey:BACKUP_STORAGE);}catch{return false;}}
function backupSettingsHtml(){return `<span class="selection-label">${onlineText(account.user?'soloImport':'guestBackup')}</span><p class="modal-note">${onlineText('backupNote')}</p>${saveBlocked?'<p class="save-warning">当前存档无法读取，已停止覆盖。请先下载备份，再导入有效存档。</p>':''}<div class="save-actions"><button class="secondary" data-action="export-save">下载存档备份</button><button class="secondary" data-action="import-save">导入存档</button></div><button class="secondary" data-action="restore-save" ${hasPreviousSave()?'':'disabled'}>恢复覆盖前存档</button>`;}
function importHtml(){const p=pendingImport;if(!p)return '';return `<p class="save-warning">导入将替换当前进度并结束本次出击。确认后保留覆盖前存档，可在设置中恢复。</p><div class="result-stats"><div><span>信用点</span><b>${number(p.credits)}</b></div><div><span>已通关小关</span><b>${Object.keys(p.clears).length} / 27</b></div><div><span>蓝图材料</span><b>${number(p.materials.blueprint)}</b></div><div><span>回声数据</span><b>${number(p.materials.data)}</b></div></div><button class="primary" data-action="confirm-import">确认导入并返回基地</button><button class="secondary" data-action="cancel-import">取消 · 保留当前进度</button>`;}
function downloadSave(){try{let text=exportProfile(profile);if(saveBlocked){try{text=localStorage.getItem(account.user?account.personalKey:STORAGE)||text;}catch{}}const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='aero-echo-save-'+new Date().toISOString().slice(0,19).replaceAll(':','-')+'.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已发起备份下载，请保管 JSON 文件。');}catch{toast('此浏览器未能下载备份，请换一个浏览器重试。');}}
function confirmImport(){if(!pendingImport||busy||!accountReady||account.conflict)return;const imported=pendingImport,key=account.user?account.personalKey:STORAGE,backup=account.user?account.backupKey:BACKUP_STORAGE;let previousBackup=null;try{previousBackup=localStorage.getItem(backup);const previous=localStorage.getItem(key);if(previous)localStorage.setItem(backup,previous);if(!account.user)localStorage.setItem(key,JSON.stringify(imported));}catch{if(previousBackup){try{localStorage.setItem(backup,previousBackup);}catch{}}toast('存档写入失败，当前进度未改变。');return;}if(coop)stopCoop();Object.assign(selection,imported.selection);Object.assign(settings,imported.settings);Object.assign(profile,imported,{selection,settings});pendingImport=null;saveBlocked=false;canSave=true;lastResult=null;lastMessage=null;game=null;audio.syncSettings();chooseLanguage(profile.language||'zh');goHome();toast(onlineText('imported'));}

function beginLoading(){busy=true;loadFailure=null;$('loading').hidden=false;$('loading-spinner').hidden=false;$('loading-retry').hidden=true;$('loading-dismiss').hidden=true;$('loading-title').textContent=tr('正在接入战场');$('loading-progress').textContent=tr('准备飞行资源');$('launch').disabled=true;}
function showLoadFailure(error,kind){const reason=error.kind==='access'?'资源访问已过期，请重新打开游戏链接。':error.kind==='timeout'?'资源加载超时，请重试。':'请检查连接后重试。';loadFailure={kind,title:kind==='initialize'?'飞行资源尚未就绪':'未能载入战场',progress:`无法读取游戏资源。\n${reason}${error.src?'\n加载失败的资源：'+(error.src.startsWith('data:')?'首领备用图':error.src.split('/').pop()):''}`};$('loading').hidden=false;$('loading-spinner').hidden=true;$('loading-title').textContent=tr(loadFailure.title);$('loading-progress').textContent=tr(loadFailure.progress);$('loading-retry').hidden=false;$('loading-dismiss').hidden=kind==='initialize';}
async function launch(){if(!accountReady){toast(onlineText('accountLoading'));return;}if(coop){toast(onlineText('leaveConfirm'));showModal('online');return;}if(!profile.language){showLanguageGate();return;}if(busy||!assets)return;if(!canLaunch(profile,selection,selectedFlow)){toast(selection.mode==='boss'?'完成本章第三小关后解锁':'通关后开放重玩');return;}exitFlight=null;beginLoading();keys.clear();pointer=null;hideModal();
 try{const stage=currentStage(),ship=SHIPS[selection.ship],skin=profile.skins[ship.id];audio.prepareSounds(stage,ship.id);audio.prepareStage(selection.chapter);void audio.unlock();await assets.forStage(stage,ship.id,skin,(n,total)=>{$('loading-progress').textContent=tr(`飞行资源 ${n} / ${total}`);});game=new Game({stage,ship:selection.ship,profile,difficulty:selection.difficulty,pace:selection.pace,onEvent:handleEvent});game.skin=skin;game.flow=selectedFlow;accumulator=0;lastFrame=performance.now();$('lobby').hidden=true;$('game-hud').hidden=false;updateFlightLabels();$('boss-hud').hidden=true;$('flight-tip').textContent=tr('按住战场任意位置拖拽移动');$('flight-tip').style.opacity='1';$('battle-message').classList.remove('visible');document.body.classList.add('battle-running');$('hud-stage').textContent=tr(`${stage.id} / ${CHAPTERS[stage.chapter].name}`);const shortNames={Dawn7:['超频','日冕'],Bastion3:['磁场','重力'],WraithX:['相位','奇点']};$('ability-label').textContent=tr(shortNames[ship.id][0]);$('ultimate-label').textContent=tr(shortNames[ship.id][1]);audio.setMode('battle',stage.chapter);game.start();updateHud();beginFlightStory();if(modalKind!=='story')$('canvas').focus({preventScroll:true});}
 catch(error){audio.setMode('lobby',selection.chapter);game=null;$('lobby').hidden=false;$('game-hud').hidden=true;document.body.classList.remove('battle-running');showLoadFailure(error,'launch');}
 finally{busy=false;$('launch').disabled=false;if(game)$('loading').hidden=true;}
}
function handleEvent(event){switch(event.type){case 'sound':audio.effect(event);break;case 'toast':toast(event.text);break;case 'haptic':if(settings.haptic&&navigator.vibrate)navigator.vibrate(18);break;case 'message':lastMessage={speaker:canonicalText(event.speaker),text:canonicalText(event.text)};$('message-speaker').textContent=tr(event.speaker);$('message-text').textContent=tr(event.text);const pilot=pilotForShip(coop?.local?.shipIndex??selection.ship);$('message-avatar').src=event.speaker.includes('WARNING')?(manifest.story?.bossPortraitFallbacks?.[game.stage.chapter]||manifest.bosses[game.stage.chapter+1].fallback):pilotImage(pilot,manifest);$('message-avatar').alt=event.speaker.includes('WARNING')?game.chapter.boss:storyText(pilot.name);$('battle-message').classList.add('visible');messageUntil=(game?.time||0)+(event.duration||3);break;case 'pause':keys.clear();pointer=null;accumulator=0;if(event.reason==='story')break;audio.setMode('paused',game.stage.chapter);audio.effect({name:'ui',action:'pause'});showModal('pause');break;case 'resume':accumulator=0;lastFrame=performance.now();audio.setMode(game.boss&&!game.boss.dead?'boss':'battle',game.stage.chapter);audio.effect({name:'ui',action:'resume'});break;case 'boss':$('boss-hud').hidden=false;$('boss-name').textContent=tr(event.name);audio.setMode('boss',game.stage.chapter);showStory(storyPages('boss',game.stage.chapter));break;case 'boss-end':audio.endBoss();audio.setMode('battle',game.stage.chapter);break;case 'phase':$('boss-phase').textContent=tr('PHASE '+pad(event.phase));break;case 'result':settleResult(event);break;}}
function settleResult(r){if(coop)return;const economy=settleEconomy(profile,r);profile.discovered=[...new Set([...profile.discovered,...r.seen])].sort((a,b)=>a-b);const matching=profile.records.filter(p=>p.id===r.stage.id&&p.difficulty===r.difficulty&&p.pace===r.pace&&p.mode===r.stage.mode);const previousBest=Math.max(0,...matching.map(p=>p.score));lastResult={...r,...economy,flow:game?.flow,previousBest};profile.records.unshift({id:r.stage.id,chapter:r.stage.chapter,substage:r.stage.substage,mode:r.stage.mode,score:r.score,win:r.win,stars:r.stars,difficulty:r.difficulty,pace:r.pace,ship:r.ship,time:r.time,date:new Date().toISOString()});profile.records=profile.records.slice(0,60);rememberClear(profile,r);if(r.win&&game?.flow==='story')profile.storyNext=missionIndex(r.stage.chapter,r.stage.substage)+1;save();audio.setMode('story',r.stage.chapter);audio.effect(r.win?'win':'lose');if(r.win&&r.stage.boss&&r.stage.chapter===8){const wasStory=game?.flow==='story';showEnding(()=>{if(wasStory){goHome();selectRoute(storyTarget(profile),'story');showModal('hangar');}else showModal('result');},economy.first);return;}if(r.win&&game?.flow==='story'){beginStoryExit();return;}if(r.win&&r.stage.boss)showStory([...storyPages('victory',r.stage.chapter),...(r.stage.chapter===8?storyPages('ending',8):[])],()=>showModal('result'));else showModal('result');}
function beginStoryExit(){storyContext=null;hideModal();keys.clear();pointer=null;game.enemies=[];game.bullets=[];game.hazards=[];game.pickups=[];game.effects=[];game.weaponEffects=[];game.particles=[];game.texts=[];game.boss=null;game.flash=0;game.player.lastHit=0;game.player.invulnerable=0;game.player.skillTime=0;game.player.ultTime=0;game.player.bombTime=0;game.player.bombPending=0;game.player.bank=0;game.lootBursts=[];$('boss-hud').hidden=true;$('battle-message').classList.remove('visible');$('flight-tip').textContent=tr('任务完成 · 返回机库');$('flight-tip').style.opacity='1';exitFlight={time:0};}
function hangarArrivalHtml(){const r=lastResult;if(!r?.win||r.flow!=='story')return '';return `<div class="hangar-arrival"><span class="eyebrow">任务完成 · 返回机库</span><h3>${r.stage.id} · ${CHAPTERS[r.stage.chapter].name} ${'★'.repeat(r.stars)}</h3><div class="wallet"><span>获得信用点 <b>+${number(r.reward)}</b></span><span>天赋点 <b>+${r.points}</b></span></div>${experienceReportHtml(r)}${materialReportHtml(r.materials)}${r.stage.boss?'<button class="secondary small" data-action="postflight-story">阅读通关剧情</button>':''}</div>`;}
function goHome(){if(ending.active)ending.cancel();if(coop){stopCoop();return;}exitFlight=null;storyContext=null;currentArt=null;if(game?.seen)profile.discovered=[...new Set([...profile.discovered,...game.seen])].sort((a,b)=>a-b);game=null;keys.clear();pointer=null;hideModal();$('lobby').hidden=false;$('game-hud').hidden=true;$('boss-hud').hidden=true;$('battle-message').classList.remove('visible');document.body.classList.remove('battle-running');audio.setMode('lobby',selection.chapter);updateLobby();}
function updateHud(){if(!game)return;const p=game.player;if(coop&&$('coop-status')){const local=coop.local;$('coop-status').hidden=false;$('coop-status').innerHTML=game.crew.map(pilot=>`<span class="${pilot.role===coop.role?'mine ':''}${pilot.alive?'':'fallen'}">${escapeHtml(pilot.name)} · ${onlineText(pilot.alive?'alive':'spectator')} ${Math.ceil(Math.max(0,pilot.player.hp))}</span>`).join('');if(!local?.alive){$('flight-tip').textContent=onlineText('deadHint');$('flight-tip').style.opacity='1';}}$('hud-score').textContent=tr(String(Math.round(game.score)).padStart(6,'0'));$('hud-combo').textContent=tr('COMBO ×'+game.combo.toFixed(2));$('hp-value').textContent=tr(Math.ceil(p.hp));$('shield-value').textContent=tr(Math.ceil(p.shield));$('hp-fill').style.width=Math.max(0,p.hp/p.maxHp*100)+'%';$('shield-fill').style.width=Math.max(0,p.shield/p.maxShield*100)+'%';$('hud-time').textContent=tr(duration(game.time));$('wave-label').textContent=tr(game.boss?'BOSS FIGHT':'WAVE '+pad(game.wave));$('wave-fill').style.width=Math.min(100,game.time/game.stage.duration*100)+'%';$('weapon-level').textContent=tr('火控 LV.'+game.weaponLevel+' · T'+game.weaponTier);$('graze-label').textContent=tr(game.ship.id==='WraithX'?`相位 ${p.stacks} / 擦弹 ${game.grazes}`:`擦弹 ${game.grazes}`);$('ability-timer').textContent=tr(p.skillTime>0?'生效中':p.skillCd>0?Math.ceil(p.skillCd)+'s':'就绪');$('ability-cooldown').style.height=(p.skillCd/(game.ship.cooldown*(1-(coop?.local?.upgrades.cooldown??game.talents.cooldown??0)*(coop?.05:.06)))*100)+'%';$('bomb-count').textContent=tr('× '+p.bombs);$('ultimate-energy').textContent=tr(Math.floor(p.energy/10)+'%');$('ultimate-charge').style.height=(p.energy/10)+'%';$('ultimate').classList.toggle('ready',p.energy>=1000);if(coop){$('boss-hud').hidden=!game.boss||game.boss.dead;if(game.boss)$('boss-name').textContent=tr(game.chapter.boss);}if(game.boss){$('boss-fill').style.width=Math.max(0,game.boss.hp/game.boss.maxHp*100)+'%';$('boss-phase').textContent=tr('PHASE '+pad(game.boss.phase));}if(game.time>7&&(!coop||coop.local?.alive))$('flight-tip').style.opacity='0';if(game.time>messageUntil)$('battle-message').classList.remove('visible');}


function cloudUrl(){return CLOUD_GAME+'?account=1';}
function authUrl(signOut=false){return new URL((signOut?'/signout-with-chatgpt':'/signin-with-chatgpt')+'?return_to='+encodeURIComponent('/game?account=1'),account.origin).href;}
function accountHtml(){let guestAvailable=false;try{guestAvailable=!!localStorage.getItem(STORAGE);}catch{}return accountPanel(account,{cloudUrl:cloudUrl(),signinUrl:authUrl(),signoutUrl:authUrl(true),guestAvailable});}
function onlineHtml(){return coopPanel(account,coop,{cloudUrl:cloudUrl(),signinUrl:authUrl(),choice:coopChoice,busy:onlineBusy});}
function accountChanged(){
 if($('account-badge'))$('account-badge').textContent=accountBadge(account);
 const stamp=JSON.stringify([account.user,account.status,!!account.conflict]);
 if(stamp!==accountRenderStamp){accountRenderStamp=stamp;if(modalKind==='account'||modalKind==='online'&&!coop)rerender();}
}
function applyAccountProfile(value,meta={}){
 accountReady=true;if(meta.source==='guest'){accountChanged();return;}if(ending.active)ending.cancel();
 if(coop){const previous=coop;coop=null;void previous.close().catch(()=>{});}
 game=null;exitFlight=null;lastResult=null;lastMessage=null;keys.clear();pointer=null;
 saveBlocked=false;const normalized=meta.userId?normalizeProfile(value):loadProfile();
 Object.assign(selection,normalized.selection);Object.assign(settings,normalized.settings);Object.assign(profile,normalized,{selection,settings});
 coopChoice={shipIndex:selection.ship,skin:profile.skins[SHIPS[selection.ship].id]};
 canSave=true;audio.syncSettings();setLocale(profile.language||'zh');applyStaticLocale(document);showLanguageGate();
 $('lobby').hidden=false;$('game-hud').hidden=true;$('loading').hidden=true;$('boss-hud').hidden=true;$('battle-message').classList.remove('visible');
 document.body.classList.remove('battle-running');audio.setMode('lobby',selection.chapter);
 if(['pause','result','online','story'].includes(modalKind))hideModal();updateLobby();accountChanged();
}
function flightAction(type){return coop?coop.action(type):type==='skill'?game?.skill():type==='bomb'?game?.bomb():game?.ultimate();}
function moveFlight(x,y){if(coop)coop.moveTo(x,y);else game?.moveTo(x,y);}
function pauseFlight(){if(coop){coop.pause();coopRenderStamp='';coopChanged();}else game?.pause();}
function resumeCoop(){if(!coop)return;coop.resume();coopRenderStamp='';coopChanged();}
async function enterCoop(kind,code){
 if(onlineBusy||!accountReady||!account.user||!assets)return;if(coop?.code){showModal('online');return;}
 onlineBusy=true;goHome();
 const session=new CoopSession({account,onEvent:handleCoopEvent,onChange:coopChanged,onStage:prepareCoopStage});
 coop=session;try{if(kind==='join')await session.join(code,coopChoice);else await session.create(coopChoice);coopRenderStamp='';coopChanged();}
 catch(error){if(coop===session){coop=null;game=null;}void session.close().catch(()=>{});toast(onlineText(error?.code==='room-full'?'full':error?.status===404?'notFound':error?.code==='same-account'?'ownRoom':'error'));showModal('online');}
 finally{onlineBusy=false;coopRenderStamp='';if(coop)coopChanged();else if(modalKind==='online')rerender();}
}
async function prepareCoopStage(stage,{crew}){
 const session=coop,current=coop?.game;if(!session||!assets)throw new Error('Flight assets unavailable');
 keys.clear();pointer=null;storyContext=null;exitFlight=null;
 $('loading').hidden=false;$('loading-spinner').hidden=false;$('loading-retry').hidden=true;$('loading-dismiss').hidden=true;
 $('loading-title').textContent=onlineText('connecting');$('loading-progress').textContent=onlineText('flightLoading');
 audio.prepareStage(stage.chapter);void audio.unlock();
 try{for(const pilot of crew)audio.prepareSounds(stage,pilot.ship.id);await assets.forStage(stage,crew[0].ship.id,crew[0].skin,(n,total)=>{$('loading-progress').textContent=tr('飞行资源 '+n+' / '+total);},crew.slice(1).map(p=>({ship:p.ship.id,skin:p.skin})));}
 finally{if(coop===session&&session.game===current)$('loading').hidden=true;}
 if(coop!==session||session.game!==current)return;
 game=session.game;game.selectPilot(session.role);updateFlightLabels();$('boss-hud').hidden=true;
 $('battle-message').classList.remove('visible');$('flight-tip').textContent=tr('按住战场任意位置拖拽移动');$('flight-tip').style.opacity='1';
 audio.setMode('battle',stage.chapter);updateHud();
}
function coopChanged(){
 if(!coop)return;game=coop.game;if(ending.active)return;
 if(game){game.selectPilot(coop.role);$('lobby').hidden=true;$('game-hud').hidden=false;document.body.classList.add('battle-running');updateFlightLabels();}
 const state=coop.state,stamp=JSON.stringify([state,coop.mission,coop.pauseFlags,coop.networkPaused,coop.failureReason,coop.room?.guest,coop.game?.crew.map(p=>[p.alive,p.points,p.ready,p.upgrades]),onlineBusy]);
 if(stamp===coopRenderStamp)return;coopRenderStamp=stamp;
 if(['playing','transition'].includes(state)){if(modalKind==='online'||modalKind==='pause')hideModal();audio.setMode(game?.boss&&!game.boss.dead?'boss':'battle',game?.stage.chapter??0);}
 else if(state!=='closed'){showModal('online');if(state==='paused')audio.setMode('paused',game?.stage.chapter??0);}
 updateHud();
}
function handleCoopEvent(event){
 if(!coop)return;
 if(event.type==='result')return;
 if(event.type==='boss'){game=coop.game;$('boss-hud').hidden=false;$('boss-name').textContent=tr(event.name);audio.setMode('boss',game.stage.chapter);return;}
 if(['sound','toast','haptic','message','boss-end','phase'].includes(event.type)){handleEvent(event);return;}
 if(event.type==='coop-over'){audio.endBoss();audio.setMode('story',game?.stage.chapter??0);audio.effect(event.win?'win':'lose');if(event.win){showEnding(()=>{coopRenderStamp='';coopChanged();},true);return;}}
 if(event.type==='coop-issue'&&!event.temporary)toast(onlineText('error'));
 if(event.type==='coop-death'&&event.role===coop.role)toast(onlineText('fallen'));
 if(event.type==='coop-revive'&&event.role===coop.role)toast(onlineText('alive'));
 coopRenderStamp='';coopChanged();
}
function stopCoop(){
 if(ending.active)ending.cancel();
 const session=coop;coop=null;coopRenderStamp='';onlineBusy=false;
 if(session)void session.close().catch(()=>{});
 game=null;keys.clear();pointer=null;accumulator=0;$('loading').hidden=true;
 if($('coop-status'))$('coop-status').hidden=true;goHome();
}

