$('bomb').addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();if(game&&!flightAction('bomb'))toast(game.player.bombs<=0?'本局爆弹已用完':'爆弹正在释放');});
$('ultimate').addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();if(game&&!flightAction('ultimate'))toast('击杀、擦弹与破坏部件积累大招能量');});
for(const id of ['ability','bomb','ultimate'])$(id).addEventListener('click',e=>{if(e.detail===0){if(id==='ability')flightAction('skill');else if(id==='bomb')flightAction('bomb');else flightAction('ultimate');}});
$('modal-body').addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,v=button.dataset.value;if(action!=='resume')audio.effect({name:'ui',action});switch(action){
 case 'account-retry':await account.initialize();break;
 case 'account-sync':if(await account.flush())toast(onlineText('saved'));else if(account.status!=='synced')toast(onlineText('syncError'));break;
 case 'account-nickname':try{await account.nickname($('account-name')?.value||'');toast(onlineText('nicknameSaved'));}catch{toast(onlineText('error'));}break;
 case 'account-guest-import':try{const text=localStorage.getItem(STORAGE);if(!text){toast(onlineText('emptyGuest'));break;}pendingImport=parseBackup(text);showModal('import');}catch{toast('存档无效或版本不兼容，当前进度未改变。');}break;
 case 'account-conflict':await account.resolveConflict(v);break;
 case 'coop-ship':coopChoice.shipIndex=Math.max(0,Math.min(2,Number(v)||0));showModal('online');break;
 case 'coop-skin':coopChoice.skin=Math.max(0,Math.min(3,Number(v)||0));showModal('online');break;
 case 'coop-create':await enterCoop('create');break;
 case 'coop-join':await enterCoop('join',($('coop-code')?.value||'').trim().toUpperCase());break;
 case 'coop-start':try{onlineBusy=true;showModal('online');await coop?.start();}catch{toast(onlineText('error'));}finally{onlineBusy=false;coopRenderStamp='';coopChanged();}break;
 case 'coop-upgrade':coop?.action('upgrade',v);coopRenderStamp='';coopChanged();break;
 case 'coop-ready':coop?.action('ready');coopRenderStamp='';coopChanged();break;
 case 'coop-resume':resumeCoop();break;
 case 'coop-leave':stopCoop();break;
 case 'coop-copy':try{await navigator.clipboard.writeText(coop.code);toast(onlineText('copied'));}catch{toast(coop?.code||'');}break;
 case 'story-next':if(storyContext){if(++storyContext.index>=storyContext.pages.length)finishStory();else showModal('story');}break;
 case 'story-skip':finishStory();break;
 case 'story-replay':replayStory(v);break;
 case 'story-art':currentArt=manifest.story?.gallery?.find(art=>art.id===Number(v));if(currentArt)showModal('art');break;
 case 'story-art-back':showModal('archive');break;
 case 'language':chooseLanguage(v);break;
 case 'chapter':{const chapter=Number(v),substage=[0,1,2].find(s=>missionCleared(profile,chapter,s));if(substage!==undefined){selectRoute({chapter,substage},'replay');rerender();}break;}
 case 'boss-chapter':if(bossUnlocked(profile,Number(v))){selectRoute({chapter:Number(v),substage:2},'boss');rerender();}break;
 case 'substage':if(missionCleared(profile,selection.chapter,Number(v))){selection.substage=Number(v);updateLobby();rerender();}break;
 case 'difficulty':selection.difficulty=v;updateLobby();rerender();break;
 case 'pace':selection.pace=v;updateLobby();rerender();break;
 case 'boss-mode':openModal('bosses');break;
 case 'ship':selection.ship=Number(v);updateLobby();rerender();break;
 case 'skin':profile.skins[SHIPS[selection.ship].id]=Number(v);updateLobby();rerender();break;
 case 'forge':if(upgradeWeapon(profile,SHIPS[selection.ship].id)){updateLobby();rerender();toast('武器品质已提升，下次出击生效。');}break;
 case 'research':if(upgradeResearch(profile,v)){updateLobby();rerender();toast('回声研究已完成，下次出击生效。');}break;
 case 'upgrade':case 'upgrade-five':if(upgradeHull(profile,action==='upgrade-five'?5:1)){updateLobby();rerender();toast(`机体强化完成 · LV.${fleetLevel(profile)}`);}break;
 case 'talent':{const talent=TALENTS.find(t=>t.id===v),level=profile.talents[v]||0;if(talent&&level<talent.max&&profile.points>0){profile.points--;profile.talents[v]=level+1;save();rerender();toast(talent.name+' · 已升级');}break;}
 case 'archive-tab':archiveTab=v;rerender();$('modal-body').scrollTop=0;break;
 case 'test-sound':settings.sound=true;settings.effects=true;audio.syncSettings();updateSoundIcon();save();if(modalKind==='settings')rerender();await audio.previewEffect(SHIPS[selection.ship].id);break;
 case 'setting':settings[v]=!settings[v];audio.syncSettings();if((v==='sound'||v==='effects')&&settings[v])await audio.unlock();updateLobby();rerender();break;
 case 'sensitivity':if(SENSITIVITIES.includes(Number(v))){settings.sensitivity=Number(v);save();rerender();}break;
 case 'handedness':if(['left','right'].includes(v)){settings.handedness=v;updateLobby();rerender();}break;
 case 'export-save':downloadSave();break;
 case 'import-save':$('save-file').click();break;
 case 'restore-save':try{pendingImport=parseBackup(localStorage.getItem(account.user?account.backupKey:BACKUP_STORAGE)||'');showModal('import');}catch{toast('存档无效或版本不兼容，当前进度未改变。');}break;
 case 'confirm-import':confirmImport();break;
 case 'cancel-import':pendingImport=null;showModal('settings');break;
 case 'open-story':openModal('story-mode');break;
 case 'story-launch':{const m=storyTarget(profile);if(m){selectRoute(m,'story');await launch();}break;}
 case 'story-new':profile.storyNext=0;selectRoute({chapter:0,substage:0},'story');save();await launch();break;
 case 'continue-launch':{const m=latestClear(profile);if(m){selectRoute(m,'story');await launch();}break;}
 case 'boss-launch':selectedFlow='boss';await launch();break;
 case 'postflight-story':if(lastResult?.win&&lastResult.stage.chapter===8){showEnding(()=>showModal('hangar'));break;}if(lastResult?.win&&lastResult.stage.boss)showStory([...storyPages('victory',lastResult.stage.chapter),...(lastResult.stage.chapter===8?storyPages('ending',8):[])],()=>showModal('hangar'));break;
 case 'launch':case 'restart':await launch();break;
 case 'resume':if(coop)resumeCoop();else{game?.resume();hideModal();}break;
 case 'settings':showModal('settings');break;
 case 'home':goHome();break;
 case 'close':closeModal();break;
 case 'next':if(lastResult?.win){if(lastResult.stage.mode==='boss')openModal('bosses');else{profile.storyNext=Math.min(27,missionIndex(lastResult.stage.chapter,lastResult.stage.substage)+1);save();goHome();selectRoute(storyTarget(profile),'story');showModal('hangar');}}break;
 case 'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('此浏览器不支持全屏，可添加到主屏幕试玩。');}catch{toast('此浏览器未开启全屏，仍可正常试玩。');}break;
 }});

function point(event){const r=$('canvas').getBoundingClientRect();return{x:(event.clientX-r.left)/r.width*W,y:(event.clientY-r.top)/r.height*H};}
$('canvas').addEventListener('pointerdown',event=>{if(game?.state!=='playing'||pointer)return;event.preventDefault();const p=point(event);moveFlight(game.player.x,game.player.y);pointer={id:event.pointerId,x:p.x,y:p.y,targetX:game.player.x,targetY:game.player.y};$('canvas').setPointerCapture(event.pointerId);});
$('canvas').addEventListener('pointermove',event=>{if(!pointer||pointer.id!==event.pointerId||game?.state!=='playing')return;event.preventDefault();const p=point(event);moveFlight(game.player.targetX+(p.x-pointer.x)*1.12*settings.sensitivity,game.player.targetY+(p.y-pointer.y)*1.12*settings.sensitivity);pointer.x=p.x;pointer.y=p.y;});
for(const name of ['pointerup','pointercancel','lostpointercapture'])$('canvas').addEventListener(name,event=>{if(pointer?.id===event.pointerId)pointer=null;});
document.addEventListener('keydown',event=>{if(ending.handleKey(event))return;if(!profile.language){if(event.key==='Tab'){const items=[...document.querySelectorAll('[data-language]')],first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}return;}if($('overlay').classList.contains('open')&&event.key==='Tab'){const items=[...$('overlay').querySelectorAll('button:not([disabled]),a[href],input')].filter(el=>!el.hidden);if(items.length){const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}return;}const key=event.key.toLowerCase();if(['escape','p'].includes(key)&&modalKind==='story'){event.preventDefault();finishStory();return;}if(['p','escape'].includes(key)&&game){event.preventDefault();if(game.state==='playing')pauseFlight();else if(game.state==='paused'){if(coop)resumeCoop();else{game.resume();hideModal();}}return;}if(game?.state!=='playing')return;if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','q','e',' '].includes(key)){event.preventDefault();const fresh=!keys.has(key)&&!event.repeat;keys.add(key);if(fresh&&key==='q')flightAction('skill');if(fresh&&key==='e')flightAction('bomb');if(fresh&&key===' ')flightAction('ultimate');}});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{ending.setPageActive(false);keys.clear();if(game?.state==='playing')pauseFlight();audio.setPageActive(false);});window.addEventListener('focus',()=>{ending.setPageActive(!document.hidden);audio.setPageActive(!document.hidden);});document.addEventListener('visibilitychange',()=>{ending.setPageActive(!document.hidden);if(document.hidden&&game?.state==='playing')pauseFlight();audio.setPageActive(!document.hidden);});

// Recover Web Audio within trusted mouse, touch and keyboard gestures.
for(const type of ['pointerdown','click','keydown'])document.addEventListener(type,()=>audio.recoverGesture(),{capture:true,passive:true});

function animationFrame(now){if(ending.active){if(coop)coop.update(0);ending.update(now);audio.update(null);lastFrame=now;requestAnimationFrame(animationFrame);return;}const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;clock+=dt;if(coop){if(game?.state==='playing'&&keys.size){let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);const length=Math.hypot(x,y)||1;if(x||y)moveFlight(game.player.targetX+x/length*game.player.speed*dt,game.player.targetY+y/length*game.player.speed*dt);}coop.update(dt);game=coop.game;}else if(game&&(game.state==='playing'||game.state==='ending')){accumulator+=dt;let count=0;while(accumulator>=1/60&&count++<4){if(game.state==='playing'&&keys.size){let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);const length=Math.hypot(x,y)||1;if(x||y)game.moveTo(game.player.targetX+x/length*game.player.speed/60,game.player.targetY+y/length*game.player.speed/60);}game.update(1/60);accumulator-=1/60;}}
 if(exitFlight&&game&&!document.hidden){exitFlight.time+=dt;game.player.x+=(W/2-game.player.x)*Math.min(1,dt*4);game.player.y-=dt*(180+exitFlight.time*400);if(game.player.y<-110){goHome();selectRoute(storyTarget(profile),'story');showModal('hangar');}}
 if(renderer)renderer.draw(game,clock,selection.chapter,game?.skin??profile.skins[SHIPS[selection.ship].id]);if(now-lastHud>70){updateHud();lastHud=now;}audio.update(game);requestAnimationFrame(animationFrame);}

async function initialize(){if(busy)return;beginLoading();try{manifest=await readManifest();imageFallbacks.clear();indexImageFallbacks(manifest);assets=new AssetStore(manifest);if(renderer)renderer.assets=assets;else renderer=new Renderer($('canvas'),assets,settings);updateLobby();audio.setMode('lobby',selection.chapter);if(!loopStarted){loopStarted=true;requestAnimationFrame(animationFrame);}$('loading').hidden=true;}catch(error){showLoadFailure(error,'initialize');}finally{busy=false;$('launch').disabled=!assets;tryEndingPreview();}}
setLocale(profile.language||'zh');applyStaticLocale(document);showLanguageGate();const initialized=initialize();void account.initialize().then(()=>{accountReady=true;accountChanged();const query=new URLSearchParams(globalThis.location?.search||'');if(query.has('account')&&profile.language&&!coop)showModal('account');tryEndingPreview();});
